/**
 * The worklet bundle generated by `npm run bundle` (see wdk.config.js).
 *
 * bare-pack emits a CommonJS module whose single export is the packed bundle
 * as a string, which is what WdkAppProvider's `bundle` prop expects.
 */
declare module '*/wdk-bundle/wdk-worklet.bundle.js' {
  const bundle: string;
  export default bundle;
}
